import{_ as a,o,c as r,a2 as t}from"./chunks/framework.BN3Eol-0.js";const g=JSON.parse('{"title":"UXD-032 — The program page: no empty sections, card rails, compact hardware, a mission pane that keeps its box","description":"","frontmatter":{},"headers":[],"relativePath":"uxs/decisions/UXD-032-program-page-card-rails-and-compact-hardware.md","filePath":"uxs/decisions/UXD-032-program-page-card-rails-and-compact-hardware.md"}'),s={name:"uxs/decisions/UXD-032-program-page-card-rails-and-compact-hardware.md"};function i(n,e,d,c,l,h){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="uxd-032-—-the-program-page-no-empty-sections-card-rails-compact-hardware-a-mission-pane-that-keeps-its-box" tabindex="-1">UXD-032 — The program page: no empty sections, card rails, compact hardware, a mission pane that keeps its box <a class="header-anchor" href="#uxd-032-—-the-program-page-no-empty-sections-card-rails-compact-hardware-a-mission-pane-that-keeps-its-box" aria-label="Permalink to &quot;UXD-032 — The program page: no empty sections, card rails, compact hardware, a mission pane that keeps its box&quot;">​</a></h1><ul><li><strong>Status</strong>: accepted (built; checked by unit tests, e2e on three projects and screenshots, not yet by the operator)</li><li><strong>Date</strong>: 2026-11-14 (proposed 2026-11-13, decided and built)</li><li><strong>Decider</strong>: the operator, 2026-11-14 — the recommendations of <code>docs/wip/2026-11-13-slice-E1-brief.md</code> §12 approved as written (E-decisions 1a, 2a, 3a, 4a, &quot;approved all E-series recommendations&quot;)</li><li><strong>Answers</strong>: PG2, PG3, PG4, PG5, PG6 of the UX feedback plan; slice E1</li><li><strong>Builds on</strong>: <a href="./UXD-012-one-page-shell">UXD-012</a> (the page shell and section label), <a href="./UXD-025-lists-carry-a-round-photo">UXD-025</a> (the round photo, which this record departs from for hardware on this page)</li><li><strong>Changes</strong>: <code>src/routes/programs/[id]/+page.svelte</code>, <code>+page.server.ts</code>, <code>+page.ts</code>, <code>src/lib/program-page.ts</code> (new), <code>src/lib/components/MiniCard.svelte</code> and <code>CardRail.svelte</code> (new), <code>src/lib/entity-thumb.ts</code> (<code>heroOfThumb</code>, <code>siteHeroOf</code>, <code>fleetHeroOf</code>), <code>src/lib/image-sizes.ts</code>, <code>src/types/program.ts</code> (<code>ProgramSeeAlso.kind</code> widened to the six kinds the data has), <code>tests/e2e/programs-page.spec.ts</code> (new)</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Sputnik drew a &quot;Hardware&quot; heading over an empty list (9 of 42 programs have no hardware row). Related programs were plain English-slug links (&quot;Esa Human&quot;) after &quot;Go deeper&quot;; surface sites were text rows; hardware was a grid of round 28 px photos; the mission pane changed height with the length of the blurb. Nine surface sites on Earth linked <code>/earth?site=&lt;id&gt;</code>, a parameter Earth reads only for launch pads (its objects read <code>object</code>).</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><ol><li><strong>A section with no rows draws nothing, label included.</strong> <code>programSections(p)</code> returns the sections that have rows, in order: Missions, On the surface, Hardware, Related programs, Go deeper, Sources (the spine and the assembly section are unchanged above them).</li><li><strong>One MiniCard for both rails (E-decision 1a).</strong> 176 px wide: a 16:9 hero, a one-line kind label (the world for a surface site, the agency for a program), a one-line title (Bebas 20 px, ellipsis), an optional one-line meta (a program&#39;s years). Border, radius and hover edge are the programs index card&#39;s. <code>CardRail</code> scrolls it sideways (native scroll, snap <code>proximity</code>, no arrows), its accessible name the section label. Names come from the program overlays, so they are localised.</li><li><strong>&quot;Go deeper&quot; drops its <code>program</code> rows (E-decision 2a)</strong> at render: every one repeats a related program. The data keeps them.</li><li><strong>Hardware is compact cards (E-decision 3a).</strong> 56 px tall, a rectangular 72×48 mini hero at the left (the fleet entry&#39;s blessed gallery slot, as it is), the name over the role. This departs from UXD-025 on <code>/programs/&lt;id&gt;</code> only: hardware has no round photo here; the mission rows keep their round photos and patches, and every other list keeps the round thumb.</li><li><strong>The mission pane keeps its box (PG4).</strong> Meta and name are one line with an ellipsis (the full text in <code>title</code>), the blurb reserves three lines (clamped at three), so the pane has one height for every mission.</li><li><strong>Earth surface links use <code>?object=</code> (E-decision 4a)</strong>: <code>surfaceSiteHref</code>. Moon, Mars and Venus keep <code>?site=</code>.</li><li><strong>No hero image is changed.</strong> Each card uses its entity&#39;s existing hero. Card data (heroes, rail cards) is resolved on the server so the route&#39;s JS budget does not grow by the thumbs manifest or the programs index.</li></ol><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>No new message key (the rails reuse <code>programs_related</code> and <code>programs_on_surface</code>).</li><li>Surface-site titles that are longer than one line at 176 px are cut with an ellipsis (the full label in <code>title</code>).</li><li>The hardware role stays English in every locale (roster text is not translated; unchanged).</li></ul>',8)])])}const m=a(s,[["render",i]]);export{g as __pageData,m as default};
